import random
from collections import deque

def shortest_path_dist(adj, u, v, max_d=5):
    if u == v: return 0
    n = len(adj)
    dist = [-1] * n
    dist[u] = 0
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= max_d:
            continue
        for y in adj[x]:
            if dist[y] == -1:
                dist[y] = dist[x] + 1
                if y == v:
                    return dist[y]
                q.append(y)
    return dist[v] if dist[v] != -1 else 999

def try_find_graph(n=26, min_d=3, max_d=6, trials=100):
    for trial in range(trials):
        adj = [[] for _ in range(n)]
        possible = [(i,j) for i in range(n) for j in range(i+1,n)]
        random.shuffle(possible)
        for a,b in possible:
            if len(adj[a]) >= max_d or len(adj[b]) >= max_d: continue
            d = shortest_path_dist(adj, a, b, 5)
            if d > 5:
                adj[a].append(b)
                adj[b].append(a)
        degs = [len(x) for x in adj]
        if min(degs) >= min_d:
            # return the edges
            edges = []
            for i in range(n):
                for j in adj[i]:
                    if i < j:
                        edges.append((i,j))
            return sorted(edges), degs, trial
    return None, None, trials

